contract InvMutTest { C c; constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {} function test(address newOwner) public { require(newOwner != address(0)); c.transferOwnership(newOwner); if (__ESBMC_reverted()) return; c.XBornID(); if (__ESBMC_reverted()) return; assert(c.balanceOf(newOwner) == c.totalDistributed()); } }

